const assetPathPrefix = "https://www.figma.com/api/mcp/asset/3c819061-dc0f-4383-b643-8c6bf9f476dd";
const imgIconsGenericClose = `${assetPathPrefix}/f4fc6.svg`;

type DialogActionsProps = {
  className?: string;
  divider?: boolean;
  fullWidth?: "False";
  oppositeAction?: boolean;
  primaryAction?: boolean;
  secondaryAction?: boolean;
};

function DialogActions({ className, divider = true, fullWidth = "False", oppositeAction = false, primaryAction = true, secondaryAction = true }: DialogActionsProps) {
  return (
    <div className={className || "bg-[var(--background\\/paper,white)] h-[68px] relative rounded-bl-[var(--radius-2,16px)] rounded-br-[var(--radius-2,16px)] w-[480px]"} data-node-id="2863:194794">
      {divider && (
        <div className="absolute h-px left-0 right-0 top-0" data-node-id="2863:194795" data-name="Divider">
          <div className="-translate-y-1/2 absolute bg-[var(--border\/divider,rgba(145,158,171,0.2))] border border-[var(--border\/border-light,#dfe2e8)] border-solid h-px left-0 right-0 top-1/2" data-node-id="I2863:194795;201:90678" data-name="layer" />
        </div>
      )}
      {oppositeAction && (
        <div className="absolute bg-white border border-[var(--error\/48\%,rgba(255,86,48,0.48))] border-solid content-stretch flex gap-[var(--button\/spacing,8px)] h-[var(--button\/\[medium\]--height,36px)] items-center justify-center left-[24px] min-w-[64px] px-[var(--button\/\[medium\]--px,16px)] rounded-[var(--button\/radius,8px)] top-[16px]" data-node-id="5683:10450" data-name="✳️ opposite action">
          <div className="[word-break:break-word] flex flex-col font-['Segoe_UI:Bold'] justify-center leading-[0] not-italic relative shrink-0 text-[14px] text-[color:var(--error\/main,#d82934)] text-center whitespace-nowrap" data-node-id="I5683:10450;1667:143769">
            <p className="leading-[24px]">Action</p>
          </div>
        </div>
      )}
      <div className="absolute content-stretch flex gap-[var(--dialog\/\[action\]--spacing,12px)] items-center right-[24px] top-[16px]" data-node-id="5683:10827">
        {secondaryAction && (
          <div className="bg-white border border-[var(--components\/button\/outlined,#637381)] border-solid content-stretch flex gap-[var(--button\/spacing,8px)] h-[36px] items-center justify-center min-w-[64px] px-[var(--button\/\[medium\]--px,16px)] relative rounded-[var(--button\/radius,8px)] shrink-0" data-node-id="2863:194796" data-name="✳️ secondary action">
            <div className="[word-break:break-word] flex flex-col font-['Segoe_UI:Bold'] justify-center leading-[0] not-italic relative shrink-0 text-[14px] text-[color:var(--text\/primary,#161c24)] text-center whitespace-nowrap" data-node-id="I2863:194796;1667:143733">
              <p className="leading-[24px]">Cancel</p>
            </div>
          </div>
        )}
        {primaryAction && (
          <div className="bg-[var(--global\/inherit\/bg,#212b36)] content-stretch flex gap-[var(--button\/spacing,8px)] h-[36px] items-center justify-center min-w-[64px] px-[var(--button\/\[medium\]--px,16px)] relative rounded-[var(--button\/radius,8px)] shrink-0" data-node-id="2863:194797" data-name="✳️ primary action">
            <div className="[word-break:break-word] flex flex-col font-['Segoe_UI:Bold'] justify-center leading-[0] not-italic relative shrink-0 text-[14px] text-[color:var(--global\/inherit\/color,white)] text-center whitespace-nowrap" data-node-id="I2863:194797;1667:129890">
              <p className="leading-[24px]">Action</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

type DialogProps = {
  className?: string;
  sizes?: "SM";
  slot?: React.ReactNode | null;
};

function Dialog({ className, sizes = "SM", slot = null }: DialogProps) {
  return (
    <div className={className || "bg-white h-[352px] overflow-clip relative rounded-[var(--radius-2,16px)] w-[444px]"} data-node-id="3581:52398">
      <DialogActions className="absolute bg-[var(--background\/paper,white)] bottom-0 h-[68px] left-px rounded-bl-[var(--radius-2,16px)] rounded-br-[var(--radius-2,16px)] w-[443px]" />
      <div className="absolute bg-[var(--background\/paper,white)] content-stretch flex gap-[var(--spacing-2,16px)] items-center left-px pl-[var(--dialog\/\[header\]--pl,24px)] pr-[var(--dialog\/\[header\]--pr,24px)] py-[var(--dialog\/\[header\]--py,24px)] rounded-tl-[var(--radius-2,16px)] rounded-tr-[var(--radius-2,16px)] top-0 w-[443px]" data-node-id="3581:52372" data-name="DialogTitle">
        <p className="[word-break:break-word] flex-[1_0_0] font-['Segoe_UI:Bold'] leading-[normal] min-w-px not-italic relative text-[18px] text-[color:var(--text\/primary,#161c24)]" data-node-id="I3581:52372;1678:112613">
          SM
        </p>
        <div className="content-stretch flex items-center justify-center relative rounded-[var(--icon-button\/radius,500px)] shrink-0 size-[24px]" data-node-id="I3581:52372;1680:105697" data-name="✳️ action">
          <div className="relative shrink-0 size-[24px]" data-node-id="I3581:52372;1680:105697;1670:141825" data-name="icons/placeholder">
            <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgIconsGenericClose} />
          </div>
        </div>
        <div className="absolute bottom-0 h-px left-0 right-0" data-node-id="I3581:52372;1680:105799" data-name="Divider">
          <div className="-translate-y-1/2 absolute bg-[var(--border\/divider,rgba(145,158,171,0.2))] border border-[var(--border\/border-light,#dfe2e8)] border-solid h-px left-0 right-0 top-1/2" data-node-id="I3581:52372;1680:105799;201:90678" data-name="layer" />
        </div>
      </div>
      <div className="absolute bottom-[85px] left-[25px] top-[85px] w-[395px]" data-node-id="5681:10214" data-name="Slot">
        {slot}
      </div>
    </div>
  );
}
